	root_hobt.Name, 
	root_hobt.Guid
FROM SJob.JobTypes root_hobt
JOIN SCore.OrganisationalUnits AS ORG ON (ORG.ID = root_hobt.OrganisationalUnitID)
JOIN SSop.Quotes AS Q ON (Q.OrganisationalUnitID = ORG.ID)
WHERE 
		(root_hobt.Guid = root_hobt.Guid)
	AND (Q.Guid = [[RecordGuid]])


', DefaultSortColumnName = N'Name', IsDefaultColumn = N'0', DetailPageUrl = N'', IsDetailWindowed = 0, EntityTypeId = 41, InformationPageUrl = N'', GroupColumn = N'', ColourHexColumn = N'#000000', ExternalSearchPageUrl = N'' WHERE ID = 93 AND RowStatus = 1 AND Code = N'JOB TYPE - QUOTES' AND NameColumn = N'Name' AND ValueColumn = N'Guid'
 AND DefaultSortColumnName = N'Name' AND IsDefaultColumn = N'0' AND DetailPageUrl = N'' AND IsDetailWindowed = 0 AND EntityTypeId = 41
 AND InformationPageUrl = N'' AND GroupColumn = N'' AND ColourHexColumn = N'#000000' AND ExternalSearchPageUrl = N''
UPDATE SUserInterface.DropDownListDefinitions SET RowStatus = 1, Code = N'GETCUSTOMRIBASTAGES', NameColumn = N'Name', ValueColumn = N'Value', SqlQuery = N'SELECT
    RS.Description AS Name,
    RS.Guid AS Value
FROM SJob.FeeAmendment root_hobt
JOIN SJob.Jobs J
    ON J.ID = root_hobt.JobID
JOIN SJob.JobRibaStageFees JRSF
    ON JRSF.JobID = J.ID
JOIN SJob.RibaStages RS
    ON RS.ID = JRSF.RibaStageID
WHERE J.Guid = [[ParentGuid]]
  AND RS.IsCustomStage = 1
  AND RS.RowStatus NOT IN (0,254)
  AND JRSF.RowStatus NOT IN (0,254)', DefaultSortColumnName = N'Value', IsDefaultColumn = N'0', DetailPageUrl = N'', IsDetailWindowed = 0, EntityTypeId = 70, InformationPageUrl = N'', GroupColumn = N'', ColourHexColumn = N'', ExternalSearchPageUrl = N'' WHERE ID = 117 AND RowStatus = 1 AND Code = N'GETCUSTOMRIBASTAGES' AND NameColumn = N'Name' AND ValueColumn = N'Value'
 AND DefaultSortColumnName = N'Value' AND IsDefaultColumn = N'0' AND DetailPageUrl = N'' AND IsDetailWindowed = 0 AND EntityTypeId = 70
